      if (lookahead == '$') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(1994); }
      if (lookahead == '%') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(2973); }
      if (lookahead == '&') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(1919); }
      if (lookahead == '\'') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(2995); }
      if (lookahead == '(') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(513); }
      if (lookahead == ')') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(494); }
      if (lookahead == '*') { lexer->get_position(lexer, &start_tags[0]); ADVANCE(1922); }
